INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > IT-Sicherheit > Risikoanalyse
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist eine Risikoanalyse notwendig, um potenzielle Sicherheitsbedrohungen eines Softwareprodukts zu identifizieren?', 2, '[{"text": "Ja", "correct": true, "because": "Sie deckt Bedrohungen systematisch auf"}, {"text": "Nein", "correct": false, "because": "Ohne Analyse fehlt die Grundlage"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Risikoanalyse ohne Kenntnis der Systemarchitektur durchgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Systemkenntnis ist essenziell für genaue Risikobewertung"}, {"text": "Ja", "correct": false, "because": "Unwissenheit führt zu ungenauen Ergebnissen"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine Risikoanalyse immer quantitative Methoden verwenden?', 2, '[{"text": "Nein", "correct": true, "because": "Qualitative Methoden sind ebenfalls effektiv"}, {"text": "Ja", "correct": false, "because": "Flexibilität in der Methodik"]]'),
('00000000-0000-0000-0000-000000000000', 'Können Risiken durch eine Risikoanalyse vollständig eliminiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Sie identifiziert Risiken, eliminiert sie aber nicht"}, {"text": "Ja", "correct": false, "because": "Elimination erfordert Maßnahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Risikoanalyse ein einmaliger Prozess während der Softwareentwicklung?', 2, '[{"text": "Nein", "correct": true, "because": "Sie sollte regelmäßig aktualisiert werden"}, {"text": "Ja", "correct": false, "because": "Kontinuierliche Anpassung nötig"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt eine Risikoanalyse primär?', 2, '[{"text": "Identifikation und Bewertung von Risiken", "correct": true, "because": "Legt Grundlage für Sicherheitsmaßnahmen"}, {"text": "Eliminierung aller Bedrohungen", "correct": false, "because": "Nicht primäres Ziel"}, {"text": "Kostenreduktion", "correct": false, "because": "Indirekte Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird häufig für die qualitative Risikoanalyse verwendet?', 3, '[{"text": "Risikomatrix", "correct": true, "because": "Bewertet Eintrittswahrscheinlichkeit und Auswirkung"}, {"text": "Monte-Carlo-Simulation", "correct": false, "because": "Quantitativ"}, {"text": "Regressionstest", "correct": false, "because": "Testmethode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist in einer Risikoanalyse am wichtigsten?', 2, '[{"text": "Risikoidentifikation", "correct": true, "because": "Ohne Identifikation keine Bewertung"}, {"text": "Risikobeseitigung", "correct": false, "because": "Folgeschritt"}, {"text": "Kostenabschätzung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Risiko wird durch eine Risikoanalyse typischerweise bewertet?', 2, '[{"text": "Datendiebstahl", "correct": true, "because": "Häufige Bedrohung für Software"}, {"text": "Hardware-Ausfall", "correct": false, "because": "Weniger softwarebezogen"}, {"text": "Geringe Benutzerfreundlichkeit", "correct": false, "because": "Kein Sicherheitsrisiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die Risikoanalyse am effektivsten?', 2, '[{"text": "Threat Modeling", "correct": true, "because": "Identifiziert Bedrohungen systematisch"}, {"text": "Texteditor", "correct": false, "because": "Ungeeignet"}, {"text": "Backup-Software", "correct": false, "because": "Schutz, nicht Analyse"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte umfasst eine Risikoanalyse typischerweise?', 4, '[{"text": "Risikoidentifikation", "correct": true, "because": "Findet Bedrohungen"}, {"text": "Risikobewertung", "correct": true, "because": "Bewertet Schwere"}, {"text": "Risikominderung", "correct": true, "because": "Plant Maßnahmen"}, {"text": "Softwareinstallation", "correct": false, "because": "Kein Analyseschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden können für die Risikoanalyse verwendet werden?', 3, '[{"text": "Risikomatrix", "correct": true, "because": "Qualitative Bewertung"}, {"text": "Threat Modeling", "correct": true, "because": "Systematische Bedrohungssuche"}, {"text": "FMEA", "correct": true, "because": "Fehlermöglichkeitsanalyse"}, {"text": "Code-Review", "correct": false, "because": "Entwicklungsschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken können in einer Risikoanalyse identifiziert werden?', 4, '[{"text": "Datendiebstahl", "correct": true, "because": "Häufige Bedrohung"}, {"text": "Ransomware", "correct": true, "because": "Verschlüsselungsangriff"}, {"text": "Phishing", "correct": true, "because": "Identitätsdiebstahl"}, {"text": "Geringe Performance", "correct": false, "because": "Kein Sicherheitsrisiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sollten bei der Risikoanalyse bewertet werden?', 3, '[{"text": "Eintrittswahrscheinlichkeit", "correct": true, "because": "Bestimmt Häufigkeit"}, {"text": "Schadensausmaß", "correct": true, "because": "Bewertet Konsequenzen"}, {"text": "Schutzmaßnahmen", "correct": true, "because": "Beeinflusst Risiko"}, {"text": "Entwicklungskosten", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Risikoanalyse?', 3, '[{"text": "Risikobewusstsein", "correct": true, "because": "Sensibilisiert für Bedrohungen"}, {"text": "Priorisierung", "correct": true, "because": "Fokussiert auf kritische Risiken"}, {"text": "Planungssicherheit", "correct": true, "because": "Ermöglicht Maßnahmen"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein direkter Vorteil"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine Risikoanalyse identifiziert potenzielle Bedrohungen. b) Sie eliminiert alle Risiken automatisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Identifikation ja, Elimination nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Systemkenntnis ist für eine Risikoanalyse essenziell. b) Sie muss immer quantitativ sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kenntnis ja, quantitativ optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Threat Modeling ist eine Methode der Risikoanalyse. b) Eine einmalige Analyse reicht für den gesamten Lebenszyklus.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Threat Modeling ja, regelmäßige Updates nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine Risikoanalyse bewertet das Schadensausmaß. b) Sie garantiert absolute Sicherheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bewertung ja, absolute Sicherheit nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Risikominderung ist Teil der Risikoanalyse. b) Sie fokussiert nur auf externe Bedrohungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Minderung ja, interne Bedrohungen auch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

